function qa180_report_query(array $d,array $tenant,array $filters):array {
    [,,$select,$from,$scope,$date,$branch,$user,$state,$texts]=$d;$where=[$scope.'=?'];$args=[$tenant['id']];
    if($date){$where[]=$date.'>=? AND '.$date.'<?';$args[]=$filters['from'];$args[]=date('Y-m-d',strtotime($filters['to'].' +1 day'));}
    foreach([[$branch,'branch'],[$user,'user'],[$state,'status']] as [$column,$key])if($column&&$filters[$key]!==''){if($key==='status'&&$filters[$key]==='overdue'&&in_array($scope,['a.tenant_id'],true)&&str_contains($from,'accounts_'))$where[]='a.balance>0 AND a.due_date<CURDATE()';else{$where[]=$column.'=?';$args[]=$filters[$key];}}
    if($filters['q']!==''&&$texts){$where[]='('.implode(' OR ',array_map(fn($column)=>$column.' LIKE ?',$texts)).')';foreach($texts as $unused)$args[]='%'.$filters['q'].'%';}
    return ['SELECT '.$select.' FROM '.$from.' WHERE '.implode(' AND ',$where),$args];
}
function qa180_reports(App $app,array $user,array $tenant):void {
    [$from,$to]=valid_report_dates_v1();$defs=[];foreach(qa180_report_definitions() as $key=>$definition)if(r3_report_can($app,$user,$tenant,$definition[1]))$defs[$key]=$definition;
    $key=(string)($_GET['dataset']??$_GET['export']??'');if($key==='')$key=array_key_first($defs)??'';if(!isset($defs[$key])){http_response_code(403);simple_error('Acceso no autorizado','Tu rol no permite consultar este reporte.');return;}
    $filters=['from'=>$from,'to'=>$to,'branch'=>trim((string)($_GET['branch']??'')),'user'=>trim((string)($_GET['user']??'')),'status'=>mb_substr(trim((string)($_GET['status']??'')),0,80),'q'=>mb_substr(trim((string)($_GET['q']??'')),0,150)];
    $branches=$app->all('SELECT id,name FROM branches WHERE tenant_id=? ORDER BY name',[$tenant['id']]);$users=$app->all('SELECT DISTINCT u.id,u.name FROM users u LEFT JOIN tenant_customers c ON c.user_id=u.id AND c.tenant_id=? LEFT JOIN driver_affiliations da ON da.user_id=u.id AND da.tenant_id=? WHERE u.tenant_id=? OR c.user_id IS NOT NULL OR da.user_id IS NOT NULL ORDER BY u.name',array_fill(0,3,$tenant['id']));
    foreach([['branch',$branches],['user',$users]] as [$field,$rows])if($filters[$field]!==''&&(!ctype_digit($filters[$field])||!in_array((int)$filters[$field],array_map('intval',array_column($rows,'id')),true)))throw new DomainException('El filtro no pertenece a este negocio.');
    [$query,$args]=qa180_report_query($defs[$key],$tenant,$filters);$page=max(1,min(10000,(int)($_GET['page']??1)));
    if(isset($_GET['csv'])||isset($_GET['export'])){
        // Release the browser session before streaming a potentially long export.
        session_release176();$app->db->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,false);$stmt=$app->db->prepare($query);$stmt->execute($args);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="fisitaap-'.$key.'-'.$from.'-'.$to.'.csv"');header('Cache-Control: private, no-store');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');$headers=[];for($column=0;$column<$stmt->columnCount();$column++)$headers[]=$stmt->getColumnMeta($column)['name'];fputcsv($out,$headers,',','"','');$first=$stmt->fetch(PDO::FETCH_ASSOC);$safe=static function($value){$value=(string)($value??'');$trim=ltrim($value);return $trim!==''&&in_array($trim[0],['=','+','-','@'],true)?"'".$value:$value;};if($first){do{fputcsv($out,array_map($safe,array_values($first)),',','"','');}while($first=$stmt->fetch(PDO::FETCH_ASSOC));}fclose($out);exit;
    }
    $rows=$app->all($query.' LIMIT 101 OFFSET '.(($page-1)*100),$args);$more=count($rows)>100;$rows=array_slice($rows,0,100);$columns=$rows?array_keys($rows[0]):[];
    admin_shell_start('Reportes',$user,$tenant,'reportes');echo '<section class="card admin-card"><form method="get"><label>Información<select class="input" name="dataset">';foreach($defs as $k=>$d)echo '<option value="'.$k.'" '.($k===$key?'selected':'').'>'.e($d[0]).'</option>';echo '</select></label><div class="split">'.field('Desde','from',$from,true,'date').field('Hasta','to',$to,true,'date').'</div>';
    foreach([['branch','Sucursal',$branches],['user','Usuario / cliente / motorizado',$users]] as [$field,$label,$options]){echo '<label>'.$label.'<select class="input" name="'.$field.'"><option value="">Todos</option>';foreach($options as $row)echo '<option value="'.(int)$row['id'].'" '.($filters[$field]===(string)$row['id']?'selected':'').'>'.e($row['name']).'</option>';echo '</select></label>';}
    echo field('Estado o movimiento exacto (opcional)','status',$filters['status']).field('Buscar','q',$filters['q']).'<button class="btn">Consultar</button> <button class="btn btn-light" name="csv" value="1">Descargar CSV</button></form><p>Ventas muestra los cobros registrados. Pedidos web muestra solicitudes: sus importes no se suman otra vez como ventas. Los catálogos, créditos e inventario muestran su estado actual. Fecha, sucursal, usuario y estado se aplican cuando existen en el módulo seleccionado.</p></section><section class="card admin-card"><h2>'.e($defs[$key][0]).'</h2><div class="table-wrap"><table class="table"><thead><tr>';foreach($columns as $column)echo '<th>'.e(ucfirst(str_replace('_',' ',$column))).'</th>';echo '</tr></thead><tbody>';foreach($rows as $row){echo '<tr>';foreach($row as $value)echo '<td>'.e((string)$value).'</td>';echo '</tr>';}echo '</tbody></table></div>';if(!$rows)echo '<p>No hay datos con estos filtros.</p>';echo '<nav>';foreach([[$page-1,'Anterior',$page>1],[$page+1,'Siguiente',$more]] as [$number,$label,$show])if($show)echo '<a class="btn btn-light" href="'.e(url('admin/reportes?'.http_build_query(['dataset'=>$key,...$filters,'page'=>$number]))).'">'.$label.'</a>';echo '</nav></section>';admin_shell_end();
}
